static void rung_6(long nv, long m, const double* x0, const double* c, double* o1, double* om){
  conv_in(x0, RE, IM, 216, 216, nv);
  conv_in(c, CR, CI, 216, 216, nv);
  for (long it = 1; it <= m; it++) {
    for (long x = 0; x < 6; x++) {
      double* pr = RE + x*288; double* pi = IM + x*288;
      for (long r = 0; r < 6; r++) kZ_p_6(pr + r*6*8, pi + r*6*8);
      for (long z = 0; z < 6; z++) kVY_6(pr + z*8, pi + z*8);
    }
    for (long f0 = 0; f0 < 36; f0++) kVXN_6(RE + f0*8, IM + f0*8, CR + f0*8, CI + f0*8);
    if (it == 1) conv_out(RE, IM, o1, 216, 216, nv);
  }
  conv_out(RE, IM, om, 216, 216, nv);
}

static void run_6(long B, long m, const double* x0, const double* c, double* o1, double* om){
  long b = 0;
  while (B - b >= GTH_6) {
    long nv = B - b; if (nv > 8) nv = 8;
    rung_6(nv, m, x0 + 2*b*216, c + 2*b*216, o1 + 2*b*216, om + 2*b*216);
    b += nv;
  }
  for (; b < B; b++) {
    deinter(x0 + 2*b*216, RE, IM, 216);
    deinter(c + 2*b*216, CR, CI, 216);
    double* snap = o1 + 2*b*216;
    double* fin  = om + 2*b*216;
    for (long it = 1; it <= m; it++) {
      pz_6(RE, IM, 0, 6, 36, 0);
      pass_y_6(RE, IM);
      pass_x_n_6(RE, IM, CR, CI, it == 1 ? snap : 0, it == m ? fin : 0);
    }
  }
}

