static void pass_y_8(double* restrict re, double* restrict im){
  for (long x = 0; x < 8; x++) {
    double* pr = re + x*64; double* pi = im + x*64;
    for (long z0 = 0; z0 < 8; z0 += 8) {
      __mmask8 mk = (8 - z0 >= 8) ? (__mmask8)0xFF : (__mmask8)((1u << (8 - z0)) - 1);
      kY_p_8(pr + z0, pi + z0, mk);
    }
  }
}
static void pass_x_n_8(double* restrict re, double* restrict im, const double* restrict cre, const double* restrict cim, double* snap, double* fin){
  for (long b0 = 0; b0 < 64; b0 += 8) {
    __mmask8 mk = (64 - b0 >= 8) ? (__mmask8)0xFF : (__mmask8)((1u << (64 - b0)) - 1);
    kX_n_8(re + b0, im + b0, cre + b0, cim + b0, snap ? snap + 2*b0 : 0, fin ? fin + 2*b0 : 0, mk);
  }
}

