static void rung_8(long nv, long m, const double* x0, const double* c, double* o1, double* om){
  for (long x = 0; x < 8; x++) {
    conv_in(x0 + 2*x*64, RE + x*520, IM + x*520, 64, 512, nv);
    conv_in(c  + 2*x*64, CR + x*520, CI + x*520, 64, 512, nv);
  }
  for (long it = 1; it <= m; it++) {
    for (long x = 0; x < 8; x++) {
      double* pr = RE + x*520; double* pi = IM + x*520;
      for (long r = 0; r < 8; r++) kZ_p_8(pr + r*8*8, pi + r*8*8);
      for (long z = 0; z < 8; z++) kVY_8(pr + z*8, pi + z*8);
    }
    for (long f0 = 0; f0 < 64; f0++) kVXN_8(RE + f0*8, IM + f0*8, CR + f0*8, CI + f0*8);
    if (it == 1) for (long x = 0; x < 8; x++) conv_out(RE + x*520, IM + x*520, o1 + 2*x*64, 64, 512, nv);
  }
  for (long x = 0; x < 8; x++) conv_out(RE + x*520, IM + x*520, om + 2*x*64, 64, 512, nv);
}

static void run_8(long B, long m, const double* x0, const double* c, double* o1, double* om){
  long b = 0;
  while (B - b >= GTH_8) {
    long nv = B - b; if (nv > 8) nv = 8;
    rung_8(nv, m, x0 + 2*b*512, c + 2*b*512, o1 + 2*b*512, om + 2*b*512);
    b += nv;
  }
  for (; b < B; b++) {
    deinter(x0 + 2*b*512, RE, IM, 512);
    deinter(c + 2*b*512, CR, CI, 512);
    double* snap = o1 + 2*b*512;
    double* fin  = om + 2*b*512;
    for (long it = 1; it <= m; it++) {
      pz_8(RE, IM, 0, 8, 64, 0);
      pass_y_8(RE, IM);
      pass_x_n_8(RE, IM, CR, CI, it == 1 ? snap : 0, it == m ? fin : 0);
    }
  }
}

