static void gsw_xz_13(const double* cre, const double* cim, int lag, int la, int snap){
  for (long g = 0; g < 13; g++) {
    for (long z = 0; z < 13; z++) {
      long off = (g*13 + z)*8;
      if (la) {
        kgX_knk_13(RE+off, IM+off, cre+off, cim+off, snap?SN1R+off:0, snap?SN1I+off:0);
      } else {
        kgX_n_13(RE+off, IM+off, cre+off, cim+off);
      }
    }
    if (la) for (long x = 0; x < 13; x++) { long o2 = (x*169 + g*13)*8; kZ_p_13(RE+o2, IM+o2); }
  }
}
static void gsw_yz_13(const double* cre, const double* cim, int lag, int la, int snap){
  for (long f = 0; f < 13; f++) {
    for (long z = 0; z < 13; z++) {
      long off = (f*169 + z)*8;
      if (!lag) { kVY_13(RE+off, IM+off); }
      else if (la) {
        kgY_knk_13(RE+off, IM+off, cre+off, cim+off, snap?SN1R+off:0, snap?SN1I+off:0);
      } else {
        kgY_n_13(RE+off, IM+off, cre+off, cim+off);
      }
    }
    if (la) for (long y = 0; y < 13; y++) { long o2 = (f*169 + y*13)*8; kZ_p_13(RE+o2, IM+o2); }
  }
}
static void rung_13(long nv, long m, const double* x0, const double* c, double* o1, double* om){
  conv_in(x0, RE, IM, 2197, 2197, nv);
  conv_in(c, CR, CI, 2197, 2197, nv);
  for (long s = 1; s <= m + 1; s++) {
    int la = (s <= m), lag = (s >= 2);
    int snap = (s == 2) && (m >= 2);
    if (s & 1) gsw_yz_13(CR, CI, lag, la, snap);
    else       gsw_xz_13(CR, CI, lag, la, snap);
  }
  if (m >= 2) conv_out(SN1R, SN1I, o1, 2197, 2197, nv);
  else        conv_out(RE, IM, o1, 2197, 2197, nv);
  conv_out(RE, IM, om, 2197, 2197, nv);
}

static void run_13(long B, long m, const double* x0, const double* c, double* o1, double* om){
  long b = 0;
  while (B - b >= GTH_13) {
    long nv = B - b; if (nv > 8) nv = 8;
    rung_13(nv, m, x0 + 2*b*2197, c + 2*b*2197, o1 + 2*b*2197, om + 2*b*2197);
    b += nv;
  }
  for (; b < B; b++) {
    deinter(x0 + 2*b*2197, RE, IM, 2197);
    deinter(c + 2*b*2197, CR, CI, 2197);
    double* snap = o1 + 2*b*2197;
    double* fin  = om + 2*b*2197;
    for (long it = 1; it <= m; it++) {
      pz_13(RE, IM, 0, 13, 169, 0);
      pass_y_13(RE, IM);
      pass_x_n_13(RE, IM, CR, CI, it == 1 ? snap : 0, it == m ? fin : 0);
    }
  }
}

