static void gsw_xz_17(const double* cre, const double* cim, int lag, int la, int snap){
  for (long g = 0; g < 17; g++) {
    for (long z = 0; z < 17; z++) {
      long off = (g*17 + z)*8;
      if (la) {
        kgX_knk_17(RE+off, IM+off, cre+off, cim+off, snap?SN1R+off:0, snap?SN1I+off:0);
      } else {
        kgX_n_17(RE+off, IM+off, cre+off, cim+off);
      }
    }
    if (la) for (long x = 0; x < 17; x++) { long o2 = (x*289 + g*17)*8; kZ_p_17(RE+o2, IM+o2); }
  }
}
static void gsw_yz_17(const double* cre, const double* cim, int lag, int la, int snap){
  for (long f = 0; f < 17; f++) {
    for (long z = 0; z < 17; z++) {
      long off = (f*289 + z)*8;
      if (!lag) { kVY_17(RE+off, IM+off); }
      else if (la) {
        kgY_knk_17(RE+off, IM+off, cre+off, cim+off, snap?SN1R+off:0, snap?SN1I+off:0);
      } else {
        kgY_n_17(RE+off, IM+off, cre+off, cim+off);
      }
    }
    if (la) for (long y = 0; y < 17; y++) { long o2 = (f*289 + y*17)*8; kZ_p_17(RE+o2, IM+o2); }
  }
}
static void rung_17(long nv, long m, const double* x0, const double* c, double* o1, double* om){
  conv_in(x0, RE, IM, 4913, 4913, nv);
  conv_in(c, CR, CI, 4913, 4913, nv);
  for (long s = 1; s <= m + 1; s++) {
    int la = (s <= m), lag = (s >= 2);
    int snap = (s == 2) && (m >= 2);
    if (s & 1) gsw_yz_17(CR, CI, lag, la, snap);
    else       gsw_xz_17(CR, CI, lag, la, snap);
  }
  if (m >= 2) conv_out(SN1R, SN1I, o1, 4913, 4913, nv);
  else        conv_out(RE, IM, o1, 4913, 4913, nv);
  conv_out(RE, IM, om, 4913, 4913, nv);
}

static void run_17(long B, long m, const double* x0, const double* c, double* o1, double* om){
  long b = 0;
  while (B - b >= GTH_17) {
    long nv = B - b; if (nv > 8) nv = 8;
    rung_17(nv, m, x0 + 2*b*4913, c + 2*b*4913, o1 + 2*b*4913, om + 2*b*4913);
    b += nv;
  }
  for (; b < B; b++) {
    deinter(x0 + 2*b*4913, RE, IM, 4913);
    deinter(c + 2*b*4913, CR, CI, 4913);
    double* snap = o1 + 2*b*4913;
    double* fin  = om + 2*b*4913;
    for (long it = 1; it <= m; it++) {
      pz_17(RE, IM, 0, 17, 289, 0);
      pass_y_17(RE, IM);
      pass_x_n_17(RE, IM, CR, CI, it == 1 ? snap : 0, it == m ? fin : 0);
    }
  }
}

