static void gsw_xz_23(const double* cre, const double* cim, int lag, int la, int snap){
  for (long g = 0; g < 23; g++) {
    for (long z = 0; z < 23; z++) {
      long off = (g*23 + z)*8;
      if (la) {
        kgX_knk_23(RE+off, IM+off, cre+off, cim+off, snap?SN1R+off:0, snap?SN1I+off:0);
      } else {
        kgX_n_23(RE+off, IM+off, cre+off, cim+off);
      }
    }
    if (la) for (long x = 0; x < 23; x++) { long o2 = (x*529 + g*23)*8; kZ_p_23(RE+o2, IM+o2); }
  }
}
static void gsw_yz_23(const double* cre, const double* cim, int lag, int la, int snap){
  for (long f = 0; f < 23; f++) {
    for (long z = 0; z < 23; z++) {
      long off = (f*529 + z)*8;
      if (!lag) { kVY_23(RE+off, IM+off); }
      else if (la) {
        kgY_knk_23(RE+off, IM+off, cre+off, cim+off, snap?SN1R+off:0, snap?SN1I+off:0);
      } else {
        kgY_n_23(RE+off, IM+off, cre+off, cim+off);
      }
    }
    if (la) for (long y = 0; y < 23; y++) { long o2 = (f*529 + y*23)*8; kZ_p_23(RE+o2, IM+o2); }
  }
}
static void rung_23(long nv, long m, const double* x0, const double* c, double* o1, double* om){
  conv_in(x0, RE, IM, 12167, 12167, nv);
  conv_in(c, CR, CI, 12167, 12167, nv);
  for (long s = 1; s <= m + 1; s++) {
    int la = (s <= m), lag = (s >= 2);
    int snap = (s == 2) && (m >= 2);
    if (s & 1) gsw_yz_23(CR, CI, lag, la, snap);
    else       gsw_xz_23(CR, CI, lag, la, snap);
  }
  if (m >= 2) conv_out(SN1R, SN1I, o1, 12167, 12167, nv);
  else        conv_out(RE, IM, o1, 12167, 12167, nv);
  conv_out(RE, IM, om, 12167, 12167, nv);
}

static void run_23(long B, long m, const double* x0, const double* c, double* o1, double* om){
  long b = 0;
  while (B - b >= GTH_23) {
    long nv = B - b; if (nv > 8) nv = 8;
    rung_23(nv, m, x0 + 2*b*12167, c + 2*b*12167, o1 + 2*b*12167, om + 2*b*12167);
    b += nv;
  }
  for (; b < B; b++) {
    deinter(x0 + 2*b*12167, RE, IM, 12167);
    deinter(c + 2*b*12167, CR, CI, 12167);
    double* snap = o1 + 2*b*12167;
    double* fin  = om + 2*b*12167;
    for (long it = 1; it <= m; it++) {
      pz_23(RE, IM, 0, 23, 529, 0);
      pass_y_23(RE, IM);
      pass_x_n_23(RE, IM, CR, CI, it == 1 ? snap : 0, it == m ? fin : 0);
    }
  }
}

