          if (1 < cnt) _mm512_storeu_pd(q + j0 + 1*rs, im1);
          if (2 < cnt) _mm512_storeu_pd(q + j0 + 2*rs, im2);
          if (3 < cnt) _mm512_storeu_pd(q + j0 + 3*rs, im3);
