static void sweep_xz_36(double* restrict re, double* restrict im, const double* restrict cre, const double* restrict cim, double* snap, double* fin, int lag, int la){
  for (long g = 0; g < 36; g++) {
    long pbo = g*40;
    for (long z0 = 0; z0 < 36; z0 += 8) {
      __mmask8 mk = (36 - z0 >= 8) ? (__mmask8)0xFF : (__mmask8)((1u << (36 - z0)) - 1);
      long off = pbo + z0;
      long offo = g*36 + z0;
      if (lag) {
        if (la) {
          kX_knk_36(re + off, im + off, cre + off, cim + off, snap ? snap + 2*offo : 0, mk);
        } else {
          kX_n_36(re + off, im + off, cre + off, cim + off, snap ? snap + 2*offo : 0, fin ? fin + 2*offo : 0, mk);
        }
      } else {
        __builtin_unreachable();
      }
    }
    if (la) pz_36(re, im, pbo, 1440, 36, 0);
  }
}
static void sweep_yz_36(double* restrict re, double* restrict im, const double* restrict cre, const double* restrict cim, double* snap, double* fin, int lag, int la){
  for (long g = 0; g < 36; g++) {
    long pbo = g*1440;
    for (long z0 = 0; z0 < 36; z0 += 8) {
      __mmask8 mk = (36 - z0 >= 8) ? (__mmask8)0xFF : (__mmask8)((1u << (36 - z0)) - 1);
      long off = pbo + z0;
      long offo = g*1296 + z0;
      if (lag) {
        if (la) {
          kY_knk_36(re + off, im + off, cre + off, cim + off, snap ? snap + 2*offo : 0, mk);
        } else {
          kY_n_36(re + off, im + off, cre + off, cim + off, snap ? snap + 2*offo : 0, fin ? fin + 2*offo : 0, mk);
        }
      } else {
        kY_p_36(re + off, im + off, mk);
      }
    }
    if (la) pz_36(re, im, pbo, 40, 36, 0);
  }
}

static void run_36(long B, long m, const double* x0, const double* c, double* o1, double* om){
  long b = 0;
  for (; b < B; b++) {
    for (long x = 0; x < 36; x++) {
      deinter_rows(x0 + 2*b*46656 + 2*x*1296, RE + x*1440, IM + x*1440, 36, 36, 40);
      deinter_rows(c  + 2*b*46656 + 2*x*1296, CR + x*1440, CI + x*1440, 36, 36, 40);
    }
    double* snap = o1 + 2*b*46656;
    double* fin  = om + 2*b*46656;
    for (long s = 1; s <= m + 1; s++) {
      int la = (s <= m), lag = (s >= 2);
      double* sn = (s == 2) ? snap : 0;
      double* fi = (s == m + 1) ? fin : 0;
      if (s & 1) sweep_yz_36(RE, IM, CR, CI, sn, fi, lag, la);
      else       sweep_xz_36(RE, IM, CR, CI, sn, fi, lag, la);
    }
  }
}

