    __m512d xr9 = _mm512_loadu_pd(re + 24*8);
    __m512d xi10 = _mm512_loadu_pd(im + 24*8);
    __m512d xr11 = _mm512_loadu_pd(re + 32*8);
    __m512d xi12 = _mm512_loadu_pd(im + 32*8);
    __m512d xr13 = _mm512_loadu_pd(re + 40*8);
    __m512d xi14 = _mm512_loadu_pd(im + 40*8);
    __m512d xr15 = _mm512_loadu_pd(re + 48*8);
    __m512d xi16 = _mm512_loadu_pd(im + 48*8);
    __m512d xr17 = _mm512_loadu_pd(re + 56*8);
    __m512d xi18 = _mm512_loadu_pd(im + 56*8);
    __m512d t19 = _mm512_add_pd(xr3, xr11);
    __m512d t20 = _mm512_add_pd(xi4, xi12);
